const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
if(window.gsap&&!reduced){gsap.from('.mast,.focus-grid',{y:14,opacity:.55,duration:.65,stagger:.09,ease:'power3.out',clearProps:'all'});const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){gsap.fromTo(e.target,{y:13,opacity:.5},{y:0,opacity:1,duration:.6,ease:'power2.out',clearProps:'all'});observer.unobserve(e.target);}}),{threshold:.08});$$('.lower,.study-tools,.week-section').forEach(e=>observer.observe(e));}
const panels={guide:['A note before you begin','Try the opposite.','<p>An assumption is something the argument needs. Negating it is a way to test that need. Change only what the sentence says, then ask whether the conclusion still follows.</p><p>Take your time with each prompt. Your place is saved as you go.</p>'],message:['In the margin · Joshua','One useful question.','<p>“Don’t ask whether it sounds right. Ask what happens without it.”</p><p>When you return to Negation Station, pay attention to the distinction between <em>some</em> and <em>all</em>. We can work through anything that feels uncertain in our next session.</p>'],session:['Saturday · 7:15 pm','A little preparation.','<p>Your next session with Joshua is on Saturday, October 24, at 7:15 pm.</p><p>Bring one argument that surprised you and one question you want to think through.</p><label for="prep">A question to bring</label><textarea class="panel-input" id="prep" rows="3" placeholder="I want to understand…"></textarea>'],practice:['On your own terms','What would you like to practise?','<p>Choose a small, focused piece of work.</p><p><button class="panel-action" data-demo="Logical reasoning">Logical reasoning ↗</button><button class="panel-action" data-demo="Reading comprehension">Reading comprehension ↗</button></p>'],profile:['Your learning space','Ada’s profile.','<p>Your preferences, saved work and reading settings stay together here.</p><p>This is an interactive visual study with sample content.</p>'],continue:['Your work · Progress saved','Ready for prompt 6.','<p><strong>Negation Station</strong></p><p>Five of twelve prompts are complete. Your practice would open here, right where you left it.</p>']};
let opener;function openPanel(key){opener=document.activeElement;const d=panels[key];$('#panel-kicker').textContent=d[0];$('#panel-title').textContent=d[1];$('#panel-body').innerHTML=d[2];$('#panel').showModal();$('#panel > .panel-action').hidden=key==='picker';if(key==='picker')initPicker();if(window.gsap&&!reduced)gsap.fromTo('#panel',{y:15,opacity:.7},{y:0,opacity:1,duration:.3,ease:'power2.out'});if(key==='message')$('.inbox span').textContent='0';if(key==='session'){const input=$('#prep');try{input.value=localStorage.getItem('lsatu-refined-studio-prep')||'';}catch{input.value='';}const status=document.createElement('span');status.className='prep-status';status.textContent=input.value?'Your question is saved on this device.':'Saved here as you type.';input.after(status);input.addEventListener('input',()=>{try{localStorage.setItem('lsatu-refined-studio-prep',input.value);status.textContent='Your question is saved on this device.';}catch{status.textContent='Could not save on this device. Copy your note before closing.';}});}}function closePanel(){$('#panel').close();opener?.focus();}
$$('[data-open]').forEach(b=>b.addEventListener('click',()=>openPanel(b.dataset.open)));$('.close').onclick=closePanel;$('.panel-action').onclick=closePanel;$('#panel').addEventListener('click',e=>{if(e.target===$('#panel'))closePanel();if(e.target.dataset.demo){$('#panel-title').textContent=e.target.dataset.demo;$('#panel-body').innerHTML='<p>Your focused practice session is ready. This prototype demonstrates the visual transition; no live study data is changed.</p>';}});$('#panel').addEventListener('cancel',()=>{setTimeout(()=>opener?.focus(),0)});$('#continue').onclick=()=>openPanel('continue');
$('.menu').onclick=()=>{let open=$('.menu').getAttribute('aria-expanded')==='true';$('.menu').setAttribute('aria-expanded',String(!open));$('#mobile-nav').hidden=open;$('.menu span').textContent=open?'＋':'−';};$$('#mobile-nav a').forEach(a=>a.onclick=()=>{$('#mobile-nav').hidden=true;$('.menu').setAttribute('aria-expanded','false');$('.menu span').textContent='＋';});
const days=[['FRIDAY · YOUR PLAN','Negation Station · 12 minutes left. A small, focused finish.','Continue your work','continue'],['SATURDAY · WITH JOSHUA','7:15 pm · Your next session. Bring one question to work through.','Prepare for your session','session'],['SUNDAY · AN OPEN DAY','Nothing planned here. Leave room, or choose a little practice.','Choose a practice','practice'],['MONDAY · READING','Reading recall · One passage, one paragraph at a time.','See your reading work','recall'],['TUESDAY · AN OPEN DAY','Nothing planned here. Your saved work is ready when you are.','Choose a practice','practice'],['WEDNESDAY · GUIDED PRACTICE','Find the flaw · Eight arguments, twenty minutes.','See your guided drill','flaw'],['THURSDAY · AN OPEN DAY','Nothing planned here. A useful place for a question or practice.','Choose a practice','practice']];let selectedDay=0;
function selectDay(b){selectedDay=+b.dataset.day;$$('.day').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});const d=days[selectedDay];$('.agenda-label').textContent=d[0];$('#day-detail').textContent=d[1];$('#agenda-action').innerHTML=d[2]+' <span>↗</span>';if(window.gsap&&!reduced)gsap.fromTo('.day-detail',{y:4,opacity:.5},{y:0,opacity:1,duration:.28,clearProps:'all'});}
$$('.day').forEach((b,i)=>{b.onclick=()=>selectDay(b);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?6:(i+(e.key==='ArrowRight'?1:6))%7;const target=$$('.day')[next];selectDay(target);target.focus();};});$('#agenda-action').onclick=()=>{const k=days[selectedDay][3];if(k==='flaw'||k==='recall')$('[data-task="'+k+'"]').click();else openPanel(k);};
const taskData={flaw:['Your next guided drill','Find the flaw.','Eight arguments. Find the gap between the reasons and the conclusion.'],recall:['Your next reading practice','Reading recall.','Read one paragraph, pause, and explain its main idea in your own words.']};$$('[data-task]').forEach(b=>b.onclick=()=>{const d=taskData[b.dataset.task];panels.selected=[d[0],d[1],'<p>'+d[2]+'</p><p class="sample-notice">Demonstration preview. The live practice opens in the connected app. Your Negation Station place remains saved.</p>'];openPanel('selected');});
$$('[data-filter]').forEach(b=>b.onclick=()=>{$$('[data-filter]').forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',String(x===b));});$$('[data-task]').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.category!==b.dataset.filter);});

// A small illustrative bank keeps this design study interactive without implying live test content.
const examples=[{kind:'LR',test:'155',section:'1',question:'1',topic:'Necessary assumptions',title:'A plan for the reading room',text:'A library will extend its evening hours. Its director predicts that more students will visit because students often ask for somewhere quiet to study after dinner.',questionText:'What would the director’s prediction need to assume?',choices:['Students who want a quiet place can reach the library during the extended hours.','Every student prefers studying in a library.','The library currently has more visitors than other study spaces.'],answer:0},{kind:'LR',test:'154',section:'2',question:'2',topic:'Argument structure',title:'The community garden',text:'The neighbourhood garden has produced more vegetables since its volunteers added compost. The coordinator concludes that compost caused the increase, although this summer also brought more rain.',questionText:'Which possibility most directly challenges the coordinator’s reasoning?',choices:['Rainfall, rather than compost, may explain the larger harvest.','Some volunteers prefer flowers to vegetables.','Compost can be made from garden waste.'],answer:0},{kind:'RC',test:'153',section:'3',question:'3',topic:'Passage purpose',title:'Reading a city',text:'Old street maps can preserve more than the shape of a city. Their omissions sometimes reveal which neighbourhoods their makers considered important. A historian who compares several maps can therefore learn about changing priorities as well as changing streets.',questionText:'What is the main purpose of this short passage?',choices:['To describe a way maps can reveal historical priorities.','To argue that modern maps are unreliable.','To explain how to draw an accurate street map.'],answer:0}];
let savedRefs;try{savedRefs=JSON.parse(localStorage.getItem('lsatu-refined-studio-saved-refs')||'[]');if(!Array.isArray(savedRefs))savedRefs=[];}catch{savedRefs=[];}
const refLabel=q=>`PT ${q.test} · ${q.kind} · Section ${q.section} · Q${q.question}`;
const refKey=q=>[q.kind,q.test,q.section,q.question].join('-');
let openedRefs;try{openedRefs=JSON.parse(localStorage.getItem('lsatu-refined-studio-opened-refs')||'[]');if(!Array.isArray(openedRefs))openedRefs=[];}catch{openedRefs=[];}
function questionFromKey(key){return examples.find(x=>refKey(x)===key);}
let currentQuestion;
function syncPicker(form){const section=form.elements.section;const previous=section.value;section.innerHTML=form.elements.kind.value==='LR'?'<option value="1">1</option><option value="2">2</option>':'<option value="3">3</option>';if([...section.options].some(o=>o.value===previous))section.value=previous;}
function selectedQuestion(form){const d=Object.fromEntries(new FormData(form));return examples.find(x=>refKey(x)===refKey(d));}
function renderQuestion(q){currentQuestion=q;openedRefs=[refKey(q),...openedRefs.filter(k=>k!==refKey(q))].slice(0,6);try{localStorage.setItem('lsatu-refined-studio-opened-refs',JSON.stringify(openedRefs));}catch{}$('#panel-kicker').textContent=refLabel(q);$('#panel-title').textContent=q.title;$('#panel-body').innerHTML=`<div class="sample-notice">Original demonstration question · Not official PrepTest content</div><p class="question-stimulus">${q.text}</p><p class="question-ask">${q.questionText}</p><fieldset class="answer-options"><legend class="sr-only">Choose an answer</legend>${q.choices.map((x,i)=>`<label><input type="radio" name="answer" value="${i}"><span>${String.fromCharCode(65+i)}.</span>${x}</label>`).join('')}</fieldset><div class="question-actions"><button class="check-answer" type="button">Check answer</button><button class="save-reference" type="button" aria-pressed="${savedRefs.includes(refKey(q))}">${savedRefs.includes(refKey(q))?'Saved to review':'Save to review'}</button></div><p class="answer-feedback" role="status"></p><button class="back-picker" type="button">← Back to question picker</button>`;$('#panel > .panel-action').hidden=true;$('#panel-title').tabIndex=-1;$('#panel-title').focus();}
function showQuestion(q){panels.question=['Question picker',q.title,''];openPanel('question');renderQuestion(q);}
panels.picker=['Practice, within reach','Find a question.','<label class="search-label" for="question-search">Reference or topic</label><input id="question-search" class="question-search" placeholder="Try PT 155 or assumptions" type="search"><div class="picker-tabs" role="group" aria-label="Question list"><button class="on" data-list="recent" aria-pressed="true">Recently opened</button><button data-list="all" aria-pressed="false">Sample questions</button><button data-list="saved" aria-pressed="false">Saved to review</button></div><p class="picker-disclaimer">Explore the interaction with three original sample questions. Your live question bank is not connected.</p><div id="question-results" aria-live="polite"></div>'];
function initPicker(){let list='recent';const render=()=>{const query=$('#question-search').value.trim().toLowerCase();const pool=list==='saved'?savedRefs.map(questionFromKey).filter(Boolean):list==='recent'?openedRefs.map(questionFromKey).filter(Boolean):examples;const items=pool.filter(q=>(refLabel(q)+' '+q.topic+' '+q.title).toLowerCase().includes(query));$('#question-results').innerHTML=items.length?items.map(q=>`<button class="question-result" data-ref="${refKey(q)}"><span><small>${refLabel(q)}</small><strong>${q.topic}</strong></span><span aria-hidden="true">↗</span></button>`).join(''):'<p class="picker-empty">'+(list==='saved'?'No matching saved questions yet. Open a sample question and save it to review.':list==='recent'?'Your recently opened questions will appear here. Choose Sample questions to explore.':'No sample questions match. Try “155”, “structure” or “reading”.')+'</p>';};$('#question-search').oninput=render;$$('[data-list]').forEach(b=>b.onclick=()=>{list=b.dataset.list;$$('[data-list]').forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',String(x===b));});render();});render();}
const quickPicker=$('#quick-picker');quickPicker.elements.kind.onchange=()=>syncPicker(quickPicker);quickPicker.onsubmit=e=>{e.preventDefault();const q=selectedQuestion(quickPicker);if(q)showQuestion(q);else{panels.unavailable=['Demonstration library','This reference is not in the sample.','<p>Three original questions are available in this prototype. The live question bank is not connected.</p><button class="panel-action" data-open-samples>Browse the three samples →</button>'];openPanel('unavailable');$('#panel-body [data-open-samples]').onclick=()=>{closePanel();openPanel('picker');$('[data-list=all]').click();};}};
$('#panel-body').addEventListener('click',e=>{const row=e.target.closest('[data-ref]');if(row){renderQuestion(questionFromKey(row.dataset.ref));return;}if(e.target.closest('.back-picker')){const p=panels.picker;$('#panel-kicker').textContent=p[0];$('#panel-title').textContent=p[1];$('#panel-body').innerHTML=p[2];initPicker();$('#question-search').focus();return;}if(e.target.closest('.save-reference')){const k=refKey(currentQuestion);savedRefs=savedRefs.includes(k)?savedRefs.filter(x=>x!==k):[...savedRefs,k];try{localStorage.setItem('lsatu-refined-studio-saved-refs',JSON.stringify(savedRefs));}catch{savedRefs=savedRefs.includes(k)?savedRefs.filter(x=>x!==k):[...savedRefs,k];$('.answer-feedback').textContent='Could not save on this device. Please try again.';}const b=e.target.closest('.save-reference');b.textContent=savedRefs.includes(k)?'Saved to review':'Save to review';b.setAttribute('aria-pressed',String(savedRefs.includes(k)));}if(e.target.closest('.check-answer')){const checked=$('input[name="answer"]:checked');$('.answer-feedback').textContent=!checked?'Choose an answer first.':+checked.value===currentQuestion.answer?currentQuestion.kind==='RC'?'Correct. The passage explains how comparing maps can reveal changing historical priorities.':currentQuestion.title==='The community garden'?'Correct. More rain provides another explanation for the larger harvest.':'Correct. Wanting a quiet place does not bring students to this library unless they can reach it during those hours.':currentQuestion.kind==='RC'?'Look for the answer that describes what the whole passage does. Does it criticize maps, teach mapmaking, or explain a use for them?':currentQuestion.title==='The community garden'?'The harvest increased, but what else changed besides the compost? Look for another possible cause.':'Consider what the argument needs, rather than a stronger claim about every case. You can try again.';}});
$$('[data-recent]').forEach(b=>b.onclick=()=>showQuestion(examples[+b.dataset.recent]));

document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'&&!e.target.closest('input,textarea,select,[contenteditable=true]')){e.preventDefault();if(!$('#panel').open)openPanel('picker');}});

function updateShelf(){const status=document.querySelector('#shelf-status');status.textContent=savedRefs.length?`${savedRefs.length} saved · ${openedRefs.length} recently opened`:openedRefs.length?`${openedRefs.length} recently opened · Save any to revisit.`:'Save a question to keep it close.';}
function updateReference(){const f=quickPicker.elements;document.querySelector('#reference-preview').textContent=`${f.test.value} / ${f.section.value} / ${f.question.value.padStart(2,'0')}`;}
quickPicker.addEventListener('change',updateReference);
document.querySelector('#panel').addEventListener('close',updateShelf);
updateShelf();updateReference();
